                ds[i][l][r] = (z % MD).toInt()
            }
        }
    }

    val dp = Array(x + 1) { IntArray(n) }
    val dq = Array(x + 1) { IntArray(n) }
    val dr = IntArray(x + 1)

    if (n > 1) {
        dp[0][n - 1] = ds[0][n - 1][n]
        dp[1][n - 1] = ds[1][n - 1][n]
        for (i in 2..x) {
