        dq[0][1] = ds[0][0][1]
        dq[1][1] = ds[1][0][1]
        for (i in 2..x) {
            for (r in 1 until n) {
                var z = ff[i - 1].toLong() * dq[i - 2][r] % MD
                for (m in r downTo 1) {
                    z += dq[i - 1][m].toLong() * ds[i - 2][m][r]
                    if (z >= (1L << 62)) z %= MD
                }
                dq[i][r] = (z % MD).toInt()
            }
        }
    }

    dr[0] = ds[0][0][n]
    dr[1] = ds[1][0][n]
    for (i in 2..x) {
        var z = (dr[i - 1].toLong() * ff[i - 2] + ff[i - 1].toLong() * dr[i - 2]) % MD
        if (n > 1) {
            for (m in 1 until n) {
                z += dq[i - 1][m].toLong() * dp[i - 2][m]
                if (z >= (1L << 62)) z %= MD
            }
        }
        dr[i] = (z % MD).toInt()
    }

    println(dr[x])
}
